def resources():
 items=[('01 / Calculator','Know what an order is worth.','Model your unit economics before deciding what you can afford to spend.','unit-economics-calculator.html','Run your numbers'),('02 / Field guide','A good ROAS can hide a bad business.','Read contribution margin alongside campaign performance.','guide-contribution-margin-roas.html','Read the guide'),('03 / Field guide','Give creative testing a method.','Turn the next round of creative into something you can learn from.','guide-creative-testing.html','Explore the approach')]
