def page(version,body):
 title='The Growth Studio' if version=='a' else 'The Commercial Imagination'
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{title} | Monday Marketing Company · Homepage {version.upper()}</title><meta name="description" content="Monday Marketing Company: creative ambition, commercial discipline. Homepage design preview."><meta property="og:title" content="{title} | Monday Marketing Company"><meta property="og:description" content="Creative ambition. Commercial discipline. Explore a new homepage direction for MMC."><meta property="og:image" content="https://www.mondaymarketing.company/assets/og-card.jpg"><link rel="icon" href="assets/logo-mark.png"><link rel="stylesheet" href="design-system/colors_and_type.css"><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="home26/home26.css"><link rel="stylesheet" href="homepage-alternatives/designs.css"></head><body><a class="hp-skip" href="#main">Skip to content</a><div id="preview-shell">{nav}</div><main class="hp hp-{version}" id="main">{body}</main><div id="preview-footer">{footer}</div><nav class="preview-switch" aria-label="Homepage design previews"><span>Compare designs</span><a href="home-studio.html" {('aria-current="page"' if version=='a' else '')}>01 · Studio</a><a href="home-editorial.html" {('aria-current="page"' if version=='b' else '')}>02 · Editorial</a></nav><script src="assets/mmc-forms.js"></script><script src="homepage-alternatives/shell.js" defer></script><script src="homepage-alternatives/interactions.js" defer></script></body></html>'''
if __name__=='__main__':
 import sys
 first='--first' in sys.argv
 (SITE/'home-studio.html').write_text(page('a',A_HERO if first else A_HERO+A_REST))
 if not first:(SITE/'home-editorial.html').write_text(page('b',B_HERO+B_REST))
 print('Built '+('first preview' if first else 'both complete homepage previews'))
